CREATE   VIEW [synapse_ce].[vwCandidatediaryentry]
AS
SELECT 
	cde.[activityid],
	cde.[subject],
	cde.[description],
	cde.[activitytypecode],
	cde.[createdon],
	cde.[createdby],
	cde.[modifiedon],
	cde.[modifiedby],
	cde.[ownerid],
	cde.[apuk_competencyid],
	cde.[regardingobjectid],
	cde.[slaid],
	cde.[prioritycode],
	cde.[deliveryprioritycode],
	cde.[apuk_competencylevel],
	cde.[instancetypecode],
	cde.[isregularactivity],
	cde.[isworkflowcreated],
	cde.[isbilled],
	cde.[ismapiprivate],
	cde.[serviceid],
	cde.[owningteam],
	cde.[owninguser],
	cde.[owningbusinessunit],
	cde.[createdonbehalfby],
	cde.[modifiedonbehalfby],
	cde.[transactioncurrencyid],
	cde.[apuk_days],
	cde.[actualstart],
	cde.[actualend],
	cde.[actualdurationminutes],
	cde.[onholdtime],
	cde.[lastonholdtime],
	cde.[scheduledstart],
	cde.[scheduledend],
	cde.[statecode],
	cde.[statuscode]
FROM synapse_ce.apuk_candidatediaryentry cde
